sys_variable_value.value:
(function execute(inputs, outputs) {

    var requestSysId = inputs.record_sys_id;
    var approverSysId = '';

    var gr = new GlideRecord('x_birl3_clm_clm_new_credit_request');
    if (gr.get(requestSysId)) {

        var sequence = [];
        try {
            sequence = JSON.parse(gr.u_approver_sequence + '');
        } catch(e) {
            gs.error('CLM Flow: invalid JSON in u_approver_sequence');
        }

        var currentOrder = parseInt(gr.u_current_approver_order) || 1;

        for (var i = 0; i < sequence.length; i++) {
            if (sequence[i].order === currentOrder) {
                approverSysId = sequence[i].user_sys_id;
                break;
            }
        }
    }

    outputs.approver_sys_id = approverSysId;

})(inputs, outputs);

